import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) {
        Deque<Integer> dq = new ArrayDeque<>();   // []
        dq.addLast(10);       // [10]
        dq.addLast(20);       // [10, 20]
        dq.addFirst(5);       // [5, 10, 20]

        System.out.println(dq.pollLast());    // returns 20  ->  [5, 10]
        System.out.println(dq.pollFirst());   // returns 5   ->  [10]
    }
}

