#include <iostream>
#include <deque>
using namespace std;

int main() {
    deque<int> dq;        // []
    dq.push_back(10);     // [10]
    dq.push_back(20);     // [10, 20]
    dq.push_front(5);     // [5, 10, 20]

    cout << dq.back() << endl;
    dq.pop_back();        // returns 20  ->  [5, 10]

    cout << dq.front() << endl;
    dq.pop_front();       // returns 5   ->  [10]

    return 0;
}

